import{_ as l,a0 as t,w as d,s as o,ao as r,I as p,x as a,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"如何在 Linux 上檢查用户所屬組 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上檢查用户所屬組 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上檢查用户所屬組 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上檢查用户所屬組 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180619 How To Check Which Groups A User Belongs To On Linux","title":"如何在 Linux 上檢查用户所屬組","tag":"201807","desc":""},"relativePath":"201807/20180619 How To Check Which Groups A User Belongs To On Linux.md","filePath":"[post].md"}'),g={name:"201807/20180619 How To Check Which Groups A User Belongs To On Linux.md"};function h(c,s,k,u,b,y){const e=t("Link");return d(),o("div",null,[s[15]||(s[15]=r(`<h1 id="如何在-linux-上檢查用户所屬組" tabindex="-1">如何在 Linux 上檢查用户所屬組 <a class="header-anchor" href="#如何在-linux-上檢查用户所屬組" aria-label="Permalink to “如何在 Linux 上檢查用户所屬組”">​</a></h1><p>將用户添加到現有組是 Linux 管理員的常規活動之一。這是一些在大環境中工作的管理員的日常活動。</p><p>甚至我會因為業務需求而在我的環境中每天都在進行這樣的活動。它是幫助你識別環境中現有組的重要命令之一。</p><p>此外，這些命令還可以幫助你識別用户所屬的組。所有用户都列在 <code>/etc/passwd</code> 中，組列在 <code>/etc/group</code> 中。</p><p>無論我們使用什麼命令，都將從這些文件中獲取信息。此外，每個命令都有其獨特的功能，可幫助用户單獨獲取所需的信息。</p><h3 id="什麼是-etc-passwd" tabindex="-1">什麼是 /etc/passwd？ <a class="header-anchor" href="#什麼是-etc-passwd" aria-label="Permalink to “什麼是 /etc/passwd？”">​</a></h3><p><code>/etc/passwd</code> 是一個文本文件，其中包含登錄 Linux 系統所必需的每個用户信息。它維護有用的用户信息，如用户名、密碼、用户 ID、組 ID、用户 ID 信息、家目錄和 shell。passwd 每行包含了用户的詳細信息，共有如上所述的 7 個字段。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &quot;daygeek&quot; /etc/passwd</span></span>
<span class="line"><span>daygeek:x:1000:1000:daygeek,,,:/home/daygeek:/bin/bash</span></span></code></pre></div><h3 id="什麼是-etc-group" tabindex="-1">什麼是 /etc/group？ <a class="header-anchor" href="#什麼是-etc-group" aria-label="Permalink to “什麼是 /etc/group？”">​</a></h3><p><code>/etc/group</code> 是一個文本文件，用於定義用户所屬的組。我們可以將多個用户添加到單個組中。它允許用户訪問其他用户文件和文件夾，因為 Linux 權限分為三類：用户、組和其他。它維護有關組的有用信息，例如組名、組密碼，組 ID（GID）和成員列表。每個都在一個單獨的行。組文件每行包含了每個組的詳細信息，共有 4 個如上所述字段。</p><p>這可以通過使用以下方法來執行。</p><ul><li><code>groups</code>： 顯示一個組的所有成員。</li><li><code>id</code>： 打印指定用户名的用户和組信息。</li><li><code>lid</code>： 顯示用户的組或組的用户。</li><li><code>getent</code>： 從 Name Service Switch 庫中獲取條目。</li><li><code>grep</code>： 代表“<ruby>全局正則表達式打印<rt>global regular expression print</rt></ruby>”，它能打印匹配的模式。</li></ul><h3 id="什麼是-groups-命令" tabindex="-1">什麼是 groups 命令？ <a class="header-anchor" href="#什麼是-groups-命令" aria-label="Permalink to “什麼是 groups 命令？”">​</a></h3><p><code>groups</code> 命令打印每個給定用户名的主要組和任何補充組的名稱。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ groups daygeek</span></span>
<span class="line"><span>daygeek : daygeek adm cdrom sudo dip plugdev lpadmin sambashare</span></span></code></pre></div><p>如果要檢查與當前用户關聯的組列表。只需運行 <code>groups</code> 命令，無需帶任何用户名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ groups</span></span>
<span class="line"><span>daygeek adm cdrom sudo dip plugdev lpadmin sambashare</span></span></code></pre></div><h3 id="什麼是-id-命令" tabindex="-1">什麼是 id 命令？ <a class="header-anchor" href="#什麼是-id-命令" aria-label="Permalink to “什麼是 id 命令？”">​</a></h3><p>id 代表 “<ruby>身份<rt>identity</rt></ruby>”。它打印真實有效的用户和組 ID。打印指定用户或當前用户的用户和組信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ id daygeek</span></span>
<span class="line"><span>uid=1000(daygeek) gid=1000(daygeek) groups=1000(daygeek),4(adm),24(cdrom),27(sudo),30(dip),46(plugdev),118(lpadmin),128(sambashare)</span></span></code></pre></div><p>如果要檢查與當前用户關聯的組列表。只運行 <code>id</code> 命令，無需帶任何用户名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ id</span></span>
<span class="line"><span>uid=1000(daygeek) gid=1000(daygeek) groups=1000(daygeek),4(adm),24(cdrom),27(sudo),30(dip),46(plugdev),118(lpadmin),128(sambashare)</span></span></code></pre></div><h3 id="什麼是-lid-命令" tabindex="-1">什麼是 lid 命令？ <a class="header-anchor" href="#什麼是-lid-命令" aria-label="Permalink to “什麼是 lid 命令？”">​</a></h3><p>它顯示用户的組或組的用户。顯示有關包含用户名的組或組名稱中包含的用户的信息。此命令需要管理員權限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lid daygeek</span></span>
<span class="line"><span> adm(gid=4)</span></span>
<span class="line"><span> cdrom(gid=24)</span></span>
<span class="line"><span> sudo(gid=27)</span></span>
<span class="line"><span> dip(gid=30)</span></span>
<span class="line"><span> plugdev(gid=46)</span></span>
<span class="line"><span> lpadmin(gid=108)</span></span>
<span class="line"><span> daygeek(gid=1000)</span></span>
<span class="line"><span> sambashare(gid=124)</span></span></code></pre></div><h3 id="什麼是-getent-命令" tabindex="-1">什麼是 getent 命令？ <a class="header-anchor" href="#什麼是-getent-命令" aria-label="Permalink to “什麼是 getent 命令？”">​</a></h3><p><code>getent</code> 命令顯示 Name Service Switch 庫支持的資料庫中的條目，它們在 <code>/etc/nsswitch.conf</code> 中配置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ getent group | grep daygeek</span></span>
<span class="line"><span>adm:x:4:syslog,daygeek</span></span>
<span class="line"><span>cdrom:x:24:daygeek</span></span>
<span class="line"><span>sudo:x:27:daygeek</span></span>
<span class="line"><span>dip:x:30:daygeek</span></span>
<span class="line"><span>plugdev:x:46:daygeek</span></span>
<span class="line"><span>lpadmin:x:118:daygeek</span></span>
<span class="line"><span>daygeek:x:1000:</span></span>
<span class="line"><span>sambashare:x:128:daygeek</span></span></code></pre></div><p>如果你只想打印關聯的組名稱，請在上面的命令中使用 <code>awk</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ getent group | grep daygeek | awk -F: &#39;{print $1}&#39;</span></span>
<span class="line"><span>adm</span></span>
<span class="line"><span>cdrom</span></span>
<span class="line"><span>sudo</span></span>
<span class="line"><span>dip</span></span>
<span class="line"><span>plugdev</span></span>
<span class="line"><span>lpadmin</span></span>
<span class="line"><span>daygeek</span></span>
<span class="line"><span>sambashare</span></span></code></pre></div><p>運行以下命令僅打印主羣組信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ getent group daygeek</span></span>
<span class="line"><span>daygeek:x:1000:</span></span></code></pre></div><h3 id="什麼是-grep-命令" tabindex="-1">什麼是 grep 命令？ <a class="header-anchor" href="#什麼是-grep-命令" aria-label="Permalink to “什麼是 grep 命令？”">​</a></h3><p><code>grep</code> 代表 “<ruby>全局正則表達式打印<rt>global regular expression print</rt></ruby>”，它能打印文件匹配的模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &quot;daygeek&quot; /etc/group</span></span>
<span class="line"><span>adm:x:4:syslog,daygeek</span></span>
<span class="line"><span>cdrom:x:24:daygeek</span></span>
<span class="line"><span>sudo:x:27:daygeek</span></span>
<span class="line"><span>dip:x:30:daygeek</span></span>
<span class="line"><span>plugdev:x:46:daygeek</span></span>
<span class="line"><span>lpadmin:x:118:daygeek</span></span>
<span class="line"><span>daygeek:x:1000:</span></span>
<span class="line"><span>sambashare:x:128:daygeek</span></span></code></pre></div><p>如果你只想打印關聯的組名稱，請在上面的命令中使用 <code>awk</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &quot;daygeek&quot; /etc/group | awk -F: &#39;{print $1}&#39;</span></span>
<span class="line"><span>adm</span></span>
<span class="line"><span>cdrom</span></span>
<span class="line"><span>sudo</span></span>
<span class="line"><span>dip</span></span>
<span class="line"><span>plugdev</span></span>
<span class="line"><span>lpadmin</span></span>
<span class="line"><span>daygeek</span></span>
<span class="line"><span>sambashare</span></span></code></pre></div><hr>`,38)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),n(e,{href:"https://www.2daygeek.com/how-to-check-which-groups-a-user-belongs-to-on-linux/"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.2daygeek.com/how-to-check-which-groups-a-user-belongs-to-on-linux/",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),n(e,{href:"https://www.2daygeek.com/author/prakash/"},{default:i(()=>[...s[2]||(s[2]=[a("Prakash Subramanian",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const C=l(g,[["render",h]]);export{f as __pageData,C as default};
